draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // character
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();

  // substance
  ctx.beginPath();
  ctx.arc(W/2 + 50 + 20 * Math.sin(t), H/2, 10, 0, 2 * Math.PI);
  ctx.stroke();

  // taking control
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2 + 50 + 20 * Math.sin(t), H/2);
  ctx.stroke();

  // chains
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 + 20 * Math.sin(t), H/2);
  ctx.lineTo(W/2 + 100 + 40 * Math.sin(t), H/2 + 20 * Math.cos(t));
  ctx.stroke();

  // character's arm
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2 + 30 * Math.cos(t), H/2 + 30 * Math.sin(t));
  ctx.stroke();

  ctx.restore();
}
